   [89]={next_id=90, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="正在专注留意周围虚粒子动静的艾丽西亚猝不及防打了个喷嚏。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她掏出终端，看了一眼时间，距离和链尉官断联已经半小时了，而周围弥漫的黑红色虚粒子雾气没有丝毫减弱。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当她看到洞天中的场景变成黎苏根的街道时，她身边的景象也发生了变化——就仿佛是两个时空发生了置换一样。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT304_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
